<section class="admin-welcome"><div><h1><?= htmlspecialchars($title) ?></h1><p>Données réelles enregistrées par la plateforme.</p></div><?php if($type==='orders'): ?><div><a class="btn secondary" href="/admin/documents">Centre documentaire</a><a class="btn secondary" href="/admin/documents/export-commandes">Export Excel</a></div><?php endif ?></section>
<section class="panel"><div class="table-toolbar"><label class="search"><i data-icon="search"></i><input data-table-search placeholder="Rechercher..."></label><span><?= count($items) ?> résultat(s)</span></div><div class="table-responsive"><table><thead><tr><?php if($type==='orders'): ?><th>RÉFÉRENCE</th><th>CLIENT</th><th>TOTAL</th><th>PAIEMENT</th><th>STATUT</th><th>DATE</th><th>DOCUMENTS</th><?php elseif($type==='users'): ?><th>UTILISATEUR</th><th>CONTACT</th><th>RÔLE</th><th>STATUT</th><th>ACTIONS</th><?php else: ?><th>PRODUIT</th><th>STOCK</th><th>PRIX</th><th>RÉFÉRENCE</th><?php endif ?></tr></thead><tbody>
