<?php if($type==='orders'): ?><td><strong><?= htmlspecialchars($item['reference']) ?></strong></td><td><?= htmlspecialchars($item['customer']) ?><br><small><?= htmlspecialchars($item['email']) ?></small></td><td><strong><?= number_format($item['total'],0,',',' ') ?> F</strong></td><td><?= htmlspecialchars($item['payment']) ?></td><td><span class="status <?= $item['status']==='paid'?'published':'draft' ?>"><?= htmlspecialchars($item['status']) ?></span></td><td><?= date('d/m/Y H:i',strtotime($item['created_at'])) ?></td><td><a class="btn secondary" target="_blank" href="/admin/documents/commande?id=<?= (int)$item['id'] ?>">Bon commande</a> <a class="btn secondary" target="_blank" href="/admin/documents/livraison?id=<?= (int)$item['id'] ?>">Livraison</a></td>
<?php elseif($type==='users'): ?><td><strong><?= htmlspecialchars($item['name']) ?></strong><br><small>Créé le <?= date('d/m/Y',strtotime($item['created_at'])) ?></small></td><td><?= htmlspecialchars($item['email']) ?><br><small><?= htmlspecialchars($item['phone']??'—') ?></small></td><td><?= $item['role']==='instructor'?'Formateur':($item['role']==='admin'?'Administrateur':'Apprenant') ?></td><td><span class="status <?= $item['status']==='active'?'published':'draft' ?>"><?= $item['status']==='active'?'Actif':'OTP en attente' ?></span></td><td><div class="table-actions"><a class="btn secondary" href="/admin/utilisateurs/modifier?id=<?= (int)$item['id'] ?>">Gérer</a><?php if($item['status']!=='active'): ?><form method="post" action="/admin/utilisateurs/activer"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn primary">Activer</button></form><?php endif ?></div></td>
<?php else: ?><td><strong><?= htmlspecialchars($item['title']) ?></strong></td><td><?= htmlspecialchars($item['stock']) ?></td><td><?= $item['price']?number_format($item['price'],0,',',' ').' F':'Sur devis' ?></td><td><?= htmlspecialchars($item['id']) ?></td><?php endif ?>
